<?php
 namespace Pterodactyl\Jobs\Dezerx; use Throwable; use DateTimeInterface; use Pterodactyl\Jobs\Job; use Pterodactyl\Models\Server; use Illuminate\Support\Facades\Log; use Illuminate\Support\Facades\Cache; use Illuminate\Support\Facades\Redis; use Illuminate\Queue\SerializesModels; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Contracts\Queue\ShouldBeEncrypted; use Illuminate\Queue\Middleware\WithoutOverlapping; use Pterodactyl\Services\Dezerx\Importer\Policy; use Pterodactyl\Services\Dezerx\Importer\Transfer; use Pterodactyl\Services\Dezerx\Importer\Credentials; use Pterodactyl\Services\Dezerx\Importer\RemoteConnection; use Pterodactyl\Services\Dezerx\Importer\RemoteFilesystem; use Pterodactyl\Services\Dezerx\Minecraft\ServerFiles; class ImportServer extends Job implements ShouldQueue, ShouldBeEncrypted { use Dispatchable; use InteractsWithQueue; use SerializesModels; public int $timeout = 10_800; public int $maxExceptions = 1; private const STATUS_TTL = 10_800; private const STOP_SECONDS = 60; private const CONCURRENCY_KEY = 'dezerx:import-concurrency:'; private const WAIT_SECONDS = 20; private const CHUNKS = 6; private const MIN_FILES_PER_CHUNK = 15; public function __construct( public Server $server, public ?int $hostProfile, public ?int $credentialProfile, public array $custom, public string $source, public string $destination, public string $mode, public bool $skipFilesCheck = false, public bool $stopServer = true, ) { } public function middleware(): array { return [ (new WithoutOverlapping('import:' . $this->server->uuid)) ->releaseAfter(30) ->expireAfter($this->timeout + 60), ]; } public function retryUntil(): DateTimeInterface { return now()->addMinutes(15); } public static function statusKey(string $server): string { return 'server-import:' . $server; } public static function chunkKey(string $server): string { return 'dezerx:import-chunks:' . $server; } public static function status(string $server): array { return Cache::get(self::statusKey($server)) ?? [ 'state' => 'idle', 'message' => '', 'startedAt' => null, 'updatedAt' => null, 'progress' => null, ]; } public static function mark(string $server, string $state, string $message, ?array $progress = null, bool $resetTimer = false): void { $existing = $resetTimer ? null : Cache::get(self::statusKey($server)); Cache::put(self::statusKey($server), [ 'state' => $state, 'message' => $message, 'startedAt' => $existing['startedAt'] ?? now()->timestamp, 'updatedAt' => now()->timestamp, 'progress' => $progress, ], self::STATUS_TTL); } public function handle(): void { $max = Policy::get()['maxConcurrent']; if ($max <= 0) { $this->run(); return; } $acquired = Redis::funnel(self::CONCURRENCY_KEY) ->limit($max) ->releaseAfter($this->timeout + 60) ->block(0) ->then(fn () => $this->run() ?? true, fn () => false); if ($acquired === false) { self::mark($this->key(), 'connecting', 'Waiting for a free import slot.'); $this->release(self::WAIT_SECONDS); } } private function run(): void { $credentials = $this->credentials(); if ($credentials === null) { $this->stop('That saved profile is gone, so there was nothing to connect to.'); return; } $client = RemoteConnection::for($credentials); $node = new ServerFiles($this->server); try { $this->import($client, $node, $credentials); } catch (Throwable $exception) { report($exception); $this->stop('That import failed part way through. Nothing further was copied.'); } finally { $client->close(); } } public function failed(?Throwable $exception): void { $this->stop('That import took too long and was stopped.'); } private function import(RemoteFilesystem $client, ServerFiles $node, Credentials $credentials): void { self::mark($this->key(), 'connecting', 'Connecting to ' . $credentials->host . '.'); $opened = $client->open(); if (!$opened['ok']) { $this->stop((string) $opened['error']); return; } $policy = Policy::get(); self::mark($this->key(), 'scanning', 'Reading what is on that host.'); $transfer = app(Transfer::class); $plan = $transfer->plan( $client, $this->source, $this->ceiling($policy), $this->bytes($policy), fn (int $found, int $bytes) => self::mark( $this->key(), 'scanning', sprintf('Reading what is on that host - %d found so far.', $found), ['current' => $found, 'total' => null, 'bytes' => $bytes], ), ); if ($plan['error'] !== null) { $this->stop($plan['error']); /* 338529 */ return; } if ($plan['files'] === 0) { $this->stop('There are no files under ' . $this->source . ' on that host.'); return; } $refusal = $this->skipFilesCheck ? null : $this->tooBig($plan, $policy); if ($refusal !== null) { $this->stop($refusal); return; } if ($this->stopServer && !$this->halt($node)) { $this->stop('The server would not stop, so nothing was copied.'); return; } if ($this->mode === 'replace') { self::mark( $this->key(), 'copying', 'Emptying the destination.', ['current' => 0, 'total' => $plan['files'], 'bytes' => 0], ); $transfer->emptyDestination($node, $this->destination); } $this->dispatchChunks($plan['fileMap']); } private function dispatchChunks(array $files): void { $total = count($files); $chunkCount = max(1, min(self::CHUNKS, intdiv($total, self::MIN_FILES_PER_CHUNK))); $buckets = array_fill(0, $chunkCount, []); $i = 0; foreach ($files as $path => $size) { $buckets[$i % $chunkCount][$path] = $size; ++$i; } $buckets = array_values(array_filter($buckets)); $key = self::chunkKey($this->key()); $redis = Redis::connection(); $redis->del($key); $redis->hset($key, 'remaining', count($buckets)); $redis->hset($key, 'seen', 0); $redis->hset($key, 'copied', 0); $redis->hset($key, 'skipped', 0); $redis->hset($key, 'failed', 0); $redis->hset($key, 'bytes', 0); $redis->expire($key, $this->timeout + 300); self::mark( $this->key(), 'copying', sprintf('Copying %d files across %d workers.', $total, count($buckets)), ['current' => 0, 'total' => $total, 'bytes' => 0], ); foreach ($buckets as $bucket) { ImportChunk::dispatch( server: $this->server, hostProfile: $this->hostProfile, credentialProfile: $this->credentialProfile, custom: $this->custom, source: $this->source, destination: $this->destination, mode: $this->mode, files: $bucket, total: $total, ); } } public static function summary(array $result): string { $message = sprintf( '%d %s copied, %s.', $result['copied'], $result['copied'] === 1 ? 'file' : 'files', self::readable($result['bytes']), ); if ($result['skipped'] > 0) { $message .= sprintf( ' %d %s skipped, either already there or too large to carry.', $result['skipped'], $result['skipped'] === 1 ? 'was' : 'were', ); } if ($result['failed'] > 0) { $message .= sprintf(' %d could not be read or written.', $result['failed']); } return $message . ' The server is stopped - start it when you have checked it over.'; } private function tooBig(array $plan, array $policy): ?string { if ($plan['truncated']) { return 'That source is larger than this panel imports in one go. Import a folder at a time, or ask an administrator to raise the limit.'; } $disk = (int) $this->server->disk; if ($disk > 0 && $plan['bytes'] > $disk * 1_048_576) { return sprintf( 'That source is %s and this server holds %d MB. Free some space or import less of it.', self::readable($plan['bytes']), $disk, ); } if ($policy['maxFiles'] > 0 && $plan['files'] > $policy['maxFiles']) { return sprintf('That source holds %d files and this panel carries %d at a time.', $plan['files'], $policy['maxFiles']); } return null; } private function ceiling(array $policy): int { return $policy['maxFiles'] > 0 ? $policy['maxFiles'] : 0; } private function bytes(array $policy): int { if ($policy['maxMegabytes'] > 0) { return $policy['maxMegabytes'] * 1_048_576; } $disk = (int) $this->server->disk; return $disk > 0 ? $disk * 1_048_576 : 0; } private function credentials(): ?Credentials { return Credentials::resolve($this->hostProfile, $this->credentialProfile, $this->custom, $this->source); } private function halt(ServerFiles $node): bool { if ($node->powerState() === 'offline') { return true; } self::mark($this->key(), 'copying', 'Stopping the server.'); $node->setPower('kill'); $deadline = microtime(true) + self::STOP_SECONDS; do { sleep(3); if ($node->powerState() === 'offline') { return true; } } while (microtime(true) < $deadline); Log::warning('A server would not stop before an import', ['server' => $this->server->uuid]); return false; } public static function readable(int $bytes): string { if ($bytes >= 1_073_741_824) { return sprintf('%.1f GB', $bytes / 1_073_741_824); } return $bytes >= 1_048_576 ? sprintf('%d MB', (int) ($bytes / 1_048_576)) : sprintf('%d KB', max(1, (int) ($bytes / 1024))); } private function stop(string $message): void { self::mark($this->key(), 'failed', $message); } private function key(): string { return $this->server->uuid; } } 